create extension if not exists pgcrypto;
create table agents (id uuid primary key default gen_random_uuid(), name text not null, token_hash text not null unique, status text not null default 'active' check (status in ('active','suspended')), created_at timestamptz not null default now());
create table policies (id uuid primary key default gen_random_uuid(), agent_id uuid not null references agents(id), version int not null, doc jsonb not null, source_text text, status text not null check (status in ('draft','active','archived')), created_at timestamptz not null default now(), confirmed_at timestamptz, unique (agent_id, version));
create unique index one_active_policy on policies(agent_id) where status = 'active';
create table calls (id uuid primary key default gen_random_uuid(), agent_id uuid not null references agents(id), tool text not null, args jsonb not null, amount_minor bigint, currency text, counterparty text, category text, decision text not null check (decision in ('allow','deny','needs_approval')), reason_codes text[] not null default '{}', status text not null check (status in ('executed','denied','pending_approval','failed','expired')), approval_id uuid, result jsonb, created_at timestamptz not null default now());
create table approvals (id uuid primary key default gen_random_uuid(), call_id uuid not null references calls(id), agent_id uuid not null references agents(id), status text not null default 'pending' check (status in ('pending','approved','denied','expired')), decided_by text, decided_at timestamptz, expires_at timestamptz not null, created_at timestamptz not null default now());
create table spend_ledger (id uuid primary key default gen_random_uuid(), agent_id uuid not null references agents(id), call_id uuid not null references calls(id), amount_minor bigint not null, currency text not null, counterparty text not null, created_at timestamptz not null default now());
create table untrusted_strings (id uuid primary key default gen_random_uuid(), agent_id uuid not null references agents(id), value_norm text not null, source_url text not null, created_at timestamptz not null default now(), unique (agent_id, value_norm));
create table audit_log (seq bigint primary key, ts timestamptz not null default now(), agent_id uuid, event_type text not null, payload jsonb not null, prev_hash char(64) not null, hash char(64) not null);
create function audit_immutable() returns trigger as $$ begin raise exception 'audit_log is append-only'; end $$ language plpgsql;
create trigger audit_immutable before update or delete on audit_log for each row execute function audit_immutable();
